using Microsoft.AspNetCore.Mvc; using System.Linq; using System.Security.Cryptography; using System.Text; using TuneHire.Api.Data; using TuneHire.Api.Models; using TuneHire.Api.Services; namespace TuneHire.Api.Controllers { [ApiController] [Route("api/[controller]")] public class AuthController : ControllerBase { private readonly AppDbContext _db; private readonly IJwtService _jwt; public AuthController(AppDbContext db, IJwtService jwt) { _db = db; _jwt = jwt; } [HttpPost("register")] public IActionResult Register([FromBody] RegisterDto dto) { if (_db.Users.Any(u => u.Email == dto.Email)) return BadRequest("Email exists"); var user = new User { Email = dto.Email, PasswordHash = Hash(dto.Password), Role = dto.Role, DisplayName = dto.DisplayName }; _db.Users.Add(user); _db.SaveChanges(); var token = _jwt.GenerateToken(user.Id, user.Role); return Ok(new { token }); } [HttpPost("login")] public IActionResult Login([FromBody] LoginDto dto) { var user = _db.Users.FirstOrDefault(u => u.Email == dto.Email); if (user == null || user.PasswordHash != Hash(dto.Password)) return Unauthorized(); var token = _jwt.GenerateToken(user.Id, user.Role); return Ok(new { token }); } private string Hash(string input) { using var sha = SHA256.Create(); var b = sha.ComputeHash(Encoding.UTF8.GetBytes(input)); return Convert.ToBase64String(b); } } public class RegisterDto { public string Email { get; set; } public string Password { get; set; } public string Role { get; set; } = "User"; public string DisplayName { get; set; } } public class LoginDto { public string Email { get; set; } public string Password { get; set; } }